        if (let1 === S.ZOMBIE) {
            return let2 === S.ZOMBIE ? 1 : 0;
        }
        if (let1 === S.MUMMY) {
            return let2 === S.MUMMY ? 1 : 0;
        }
        if (let1 === S.VAMPIRE) {
            return let2 === S.VAMPIRE ? 1 : 0;
        }
        if (let1 === S.LICH) {
            return let2 === S.LICH ? 1 : 0;
        }
        if (let1 === S.WRAITH) {
            return let2 === S.WRAITH ? 1 : 0;
        }
        if (let1 === S.GHOST) {
            return let2 === S.GHOST ? 1 : 0;
        }
